  vi.useRealTimers();
});

test('shows a notification after clicking the corner button and hides it automatically', async () => {
  vi.useFakeTimers();
  const userEvent = await import('@testing-library/user-event');
  const user = userEvent.default.setup({ advanceTimers: vi.advanceTimersByTime });
  const toaster = new Toaster();

  render(
    <ThemeProvider theme=\"light\">
      <ToasterProvider toaster={toaster}>
        <App />
        <ToasterComponent />
      </ToasterProvider>
    </ThemeProvider>,
  );

  expect(screen.queryByRole('heading', { name: 'Готово"'!'"' })).toBeNull();

  await user.click(screen.getByRole('button', { name: 'Показать уведомление' }));

  expect(screen.getByRole('heading', { name: 'Готово"'!'"' })).toBeInTheDocument();

  await vi.advanceTimersByTimeAsync(3000);

  expect(screen.queryByRole('heading', { name: 'Готово"'!'"' })).toBeNull();
});
